(()=>{
 'use strict';
 let user=null,busy=false,message='',report=null,history=[],confirmed=false,version=0;
 async function api(url,method='GET',body){const r=await fetch('/api/'+url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось выполнить запрос.');return d;}
 const safe=x=>esc(String(x??'').replace(/\\(?:frac|text|cdot|times|left|right)|[\\`#*]/g,'').trim());
 function reportHTML(r){return `<section class="card"><h2>Результат разбора</h2><p>${safe(r.summary)}</p><h3>Ошибки в работе</h3>${r.errors.length?r.errors.map(e=>`<article class="diagnostic-error"><h3>${safe(e.topic)}</h3><p>В работе: ${safe(e.fragment)}</p><p>${safe(e.problem)}</p><p>Как исправить: ${safe(e.correction)}</p></article>`).join(''):'<p>Подтверждённых ошибок в доступной записи не найдено.</p>'}<h3>Темы для повторения</h3>${r.topics.map(t=>`<article class="diagnostic-error"><h3>${safe(t.title)}</h3><p>${safe(t.reason)}</p><p>Попробуй: ${safe(t.practice)}</p></article>`).join('')||'<p>Тем для повторения по этой работе пока нет.</p>'}${r.limitations.map(t=>`<p>${safe(t)}</p>`).join('')}</section>`;}
 scan=()=>`${head('РАЗБОР РАБОТЫ','Проверка с Gemini','Прочитаем рукопись, разберём ошибки и выберем темы для повторения.')}<section class="card scan-panel"><p>${user?'Профиль: '+safe(user.name):'Для проверки войди в профиль. Материалы доступны без входа.'}</p><p>При нажатии «Прочитать фото» страницы отправляются в Google Gemini. На сайте сохраняются текст и разбор, фотографии в базу не записываются.</p><label class="upload-zone" for="photoInput"><strong>Выбрать фотографии</strong><small>До четырёх страниц JPG, PNG или WEBP, до 8 МБ каждая</small><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" multiple ${busy?'disabled':''}></label><div class="upload-previews">${state.photos.map((p,i)=>`<div><img src="${esc(p.url)}" alt="Страница ${i+1}"><button class="btn btn-light" data-ai-remove="${i}" ${busy?'disabled':''}>Убрать</button></div>`).join('')}</div><button class="btn btn-blue" data-ai-ocr ${!user||busy||!state.photos.length?'disabled':''}>Прочитать фото</button><p role="status" aria-live="polite">${safe(message)}</p><label for="scanText">Проверь распознанный текст или введи работу вручную</label><textarea id="scanText" class="textarea" ${busy?'disabled':''}>${esc(state.scanText)}</textarea><label><input type="checkbox" id="aiConfirm" ${confirmed?'checked':''} ${busy?'disabled':''}>Текст совпадает с работой ученика</label><div class="task-actions"><button class="btn btn-orange" data-ai-analyze ${!user||busy||!confirmed||!state.scanText.trim()?'disabled':''}>Разобрать ошибки и выбрать темы</button></div><p>Можно проверить несколько задач за один раз. Включи условия и решения, чтобы было понятно, что требовалось сделать.</p></section>${report?reportHTML(report):''}`;
 const originalProfile=profile;
 profile=()=>originalProfile()+`<section class="card"><h2>Профиль на сервере</h2>${user?`<p>${safe(user.name)}</p><button class="btn btn-light" data-server-logout>Выйти</button><p>Прогресс и разборы доступны после входа на другом устройстве.</p>`:'<a class="btn btn-blue" href="index.html#login">Войти или зарегистрироваться</a>'}<h3>История разборов</h3>${history.map(w=>`<article><p>${new Date(w.created).toLocaleString('ru-RU')}</p><button class="btn btn-light" data-ai-open="${w.id}">Открыть разбор</button><button class="btn btn-light" data-ai-delete="${w.id}">Удалить</button></article>`).join('')||'<p>Сохранённых разборов пока нет.</p>'}</section>`;
 let timer,pending=Promise.resolve();const localSave=save;
 save=()=>{if(!user){localSave();return;}if(user){clearTimeout(timer);timer=setTimeout(()=>{const snapshot={grade:state.grade,results:state.results};pending=pending.catch(()=>{}).then(()=>api('progress','PUT',snapshot)).catch(e=>toast(e.message));},350);}};
 document.addEventListener('input',e=>{if(e.target.id==='scanText'){confirmed=false;report=null;version++;const c=document.getElementById('aiConfirm');if(c)c.checked=false;document.querySelector('[data-ai-analyze]')?.setAttribute('disabled','');}});
 document.addEventListener('change',e=>{if(e.target.id==='aiConfirm'){confirmed=e.target.checked;render();}if(e.target.id==='photoInput'){confirmed=false;report=null;message='Фото добавлено. Нажми «Прочитать фото».';version++;render();}});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.aiRemove!==undefined&&!busy){URL.revokeObjectURL(state.photos[Number(b.dataset.aiRemove)].url);state.photos.splice(Number(b.dataset.aiRemove),1);confirmed=false;report=null;render();return;}
  if(b.hasAttribute('data-server-logout')){await api('auth/logout','POST',{});location.assign('index.html');return;}
  if(b.dataset.aiOpen){const w=history.find(w=>w.id===b.dataset.aiOpen);if(w){report=w.report;state.scanText=w.text;confirmed=true;go('scan');}return;}
  if(b.dataset.aiDelete){try{await api('works/'+b.dataset.aiDelete,'DELETE',{});history=history.filter(w=>w.id!==b.dataset.aiDelete);render();}catch(e){toast(e.message);}return;}
  const ocr=b.hasAttribute('data-ai-ocr'),analyze=b.hasAttribute('data-ai-analyze');if((!ocr&&!analyze)||busy)return;
  busy=true;message=ocr?'Gemini читает страницы…':'Gemini проверяет решение…';const current=version;report=null;render();
  try{if(ocr){const images=await Promise.all(state.photos.map(p=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото.'));reader.readAsDataURL(p.file);})));const result=await api('ocr','POST',{images});if(version===current){state.scanText=result.text;confirmed=false;message=(result.readable?'Текст прочитан. Сравни его с фотографией.':'Часть работы не читается. Сделай более чёткое фото.')+' '+result.uncertain.join(' ');}}else{const w=await api('analysis','POST',{text:state.scanText,confirmed,grade:state.grade});history.unshift(w);if(version===current){report=w.report;message='Разбор сохранён в профиле.';}}}catch(e){message=e.message;}finally{busy=false;render();}
 });
 (async()=>{try{user=await api('me');const progress=await api('progress');state.grade=progress.grade;state.results=progress.results;history=await api('works');}catch(e){message=e.message;}render();})();
 render();
})();

